-- ── story 4-2a: the order header fields ──────────────────────────────────
-- Generated by drizzle-kit (the four column statements) and hand-amended
-- around the generated part: the fail-fast guard, the three CHECKs and the
-- post-migration probe (drizzle-kit is blind to CHECKs; `bun run db:generate`
-- afterwards reports "No schema changes").
--
-- Four columns on `orders`, all create-only (no amend command exists):
--   * `order_type text NULL` — `b2b` | `b2c` (`ORDER_TYPES`,
--     src/modules/outbound/order-urgency.ts). Every order created from 4-2a on
--     stores one (derived from the consignee GSTIN when the caller sends none);
--     NULL is the legacy arm — an order created before 4-2a (or by an old pod
--     during a rolling deploy), shown as "—".
--   * `priority text NOT NULL DEFAULT 'normal'` — `normal` | `high` | `urgent`
--     (`ORDER_PRIORITIES`). A constant default, so the ADD COLUMN is
--     metadata-only (no rewrite); every existing row reads `normal`, which is
--     true — it had none.
--   * `ship_by_date date NULL` — an IST calendar date, "ship by the end of that
--     IST day".
--   * `cod_amount_paise bigint NULL` — the cash the courier collects, integer
--     paise 1..1_000_000_000 (₹1 crore). NULL is prepaid. There is no separate
--     payment-mode column, so the two can never disagree.
--
-- The three CHECKs are added NOT VALID (guide §3): `orders` is the large table
-- every outbound flow writes, and a VALID add would scan it under the ADD
-- COLUMN's ACCESS EXCLUSIVE lock. NOT VALID still enforces every insert and
-- update from this migration on, and every existing row satisfies all three by
-- construction (the new columns are NULL or 'normal' on it). No VALIDATE here:
-- the migrator runs the whole pending set in ONE transaction, so a VALIDATE
-- would scan under that same lock — it is a PENDING entry instead.
-- `IS NULL OR` comes first on the two nullable columns (guide §3 — a CHECK
-- admits NULL, so the NULL arm is stated, not implied).
--
-- Nothing else: no backfill, no new lookup structure (no list sorts or filters
-- by these fields in this story).
--
-- Lock cost: each ADD COLUMN takes a brief ACCESS EXCLUSIVE lock (no rewrite);
-- the NOT VALID ADD CONSTRAINTs take it without a scan. The deploy migrator
-- sets `lock_timeout` on every connection (MIGRATE_LOCK_TIMEOUT_MS, default
-- 5 s): if the lock cannot be taken the deploy fails cleanly and is re-run
-- (DEPLOY.md §5).

-- ── 0. fail-fast: any of the four columns already present ────────────────
DO $$
DECLARE
	present text;
BEGIN
	SELECT string_agg(column_name::text, ', ' ORDER BY column_name)
	  INTO present
	  FROM information_schema.columns
	 WHERE table_schema = 'public' AND table_name = 'orders'
	   AND column_name IN ('order_type', 'priority', 'ship_by_date', 'cod_amount_paise');
	IF present IS NOT NULL THEN
		RAISE EXCEPTION 'migration 0093: orders already has % — this migration has already been applied.', present;
	END IF;
END $$;
--> statement-breakpoint
ALTER TABLE "orders" ADD COLUMN "order_type" text;--> statement-breakpoint
ALTER TABLE "orders" ADD COLUMN "priority" text DEFAULT 'normal' NOT NULL;--> statement-breakpoint
ALTER TABLE "orders" ADD COLUMN "ship_by_date" date;--> statement-breakpoint
ALTER TABLE "orders" ADD COLUMN "cod_amount_paise" bigint;--> statement-breakpoint
-- ── hand-amended: the CHECKs (migration SQL only), NOT VALID ─────────────
-- Mirrored by ORDER_TYPES / ORDER_PRIORITIES / MAX_COD_AMOUNT_PAISE
-- (src/modules/outbound/order-urgency.ts), pinned against these definitions by
-- test/order-fields.spec.ts.
ALTER TABLE "orders" ADD CONSTRAINT "orders_order_type_check" CHECK (
	"order_type" IS NULL OR "order_type" IN ('b2b','b2c')
) NOT VALID;--> statement-breakpoint
ALTER TABLE "orders" ADD CONSTRAINT "orders_priority_check" CHECK (
	"priority" IN ('normal','high','urgent')
) NOT VALID;--> statement-breakpoint
ALTER TABLE "orders" ADD CONSTRAINT "orders_cod_amount_paise_check" CHECK (
	"cod_amount_paise" IS NULL OR ("cod_amount_paise" > 0 AND "cod_amount_paise" <= 1000000000)
) NOT VALID;--> statement-breakpoint
-- ── the post-migration assertion (the 0088 model) ─────────────────────────
-- Made-up uuids. (a) The three CHECKs are present and NOT VALID. (b) An
-- insert that omits `priority` reads back 'normal'. (c) The accepted shapes
-- are inserted and rolled back by a sentinel exception, so a CHECK that
-- refused everything fails the migration. (d) Each refused shape runs in its
-- own subtransaction and must be refused BY ITS NAMED CONSTRAINT.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	c uuid := gen_random_uuid();
	o uuid;
	read_priority text;
	refused_by text;
	expected text;
	probe text;
	unvalidated int;
BEGIN
	-- (a) all three present and NOT VALID.
	SELECT count(*) INTO unvalidated
	  FROM pg_constraint
	 WHERE conrelid = 'public.orders'::regclass
	   AND conname IN ('orders_order_type_check', 'orders_priority_check', 'orders_cod_amount_paise_check')
	   AND contype = 'c'
	   AND NOT convalidated;
	IF unvalidated <> 3 THEN
		RAISE EXCEPTION 'migration 0093: expected the three order-field CHECKs present and NOT VALID, found % so.', unvalidated;
	END IF;
	-- (b) + (c) the omitted-priority default and the accepted shapes.
	BEGIN
		o := gen_random_uuid();
		INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id") VALUES (o, t, c, w);
		SELECT "priority" INTO read_priority FROM "orders" WHERE "id" = o;
		IF read_priority IS DISTINCT FROM 'normal' THEN
			RAISE EXCEPTION 'migration 0093: an order inserted without a priority read back % (expected normal).', coalesce(read_priority, 'NULL');
		END IF;
		INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","order_type","priority","ship_by_date","cod_amount_paise")
		VALUES
			(gen_random_uuid(), t, c, w, NULL, 'normal', NULL, NULL),
			(gen_random_uuid(), t, c, w, 'b2b', 'high', DATE '2026-10-24', 1),
			(gen_random_uuid(), t, c, w, 'b2c', 'urgent', DATE '2027-10-24', 1000000000),
			(gen_random_uuid(), t, c, w, 'b2c', 'normal', NULL, 149900);
		RAISE EXCEPTION USING ERRCODE = 'P0093', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0093: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0093' THEN
			NULL;
	END;
	-- (d) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY['type b2x', 'priority low', 'priority null', 'cod 0', 'cod -1', 'cod 1000000001'] LOOP
		refused_by := NULL;
		expected := CASE
			WHEN probe = 'type b2x' THEN 'orders_order_type_check'
			WHEN probe IN ('priority low') THEN 'orders_priority_check'
			WHEN probe = 'priority null' THEN 'not-null'
			ELSE 'orders_cod_amount_paise_check'
		END;
		BEGIN
			CASE probe
				WHEN 'type b2x' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","order_type")
					VALUES (gen_random_uuid(), t, c, w, 'b2x');
				WHEN 'priority low' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","priority")
					VALUES (gen_random_uuid(), t, c, w, 'low');
				WHEN 'priority null' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","priority")
					VALUES (gen_random_uuid(), t, c, w, NULL);
				WHEN 'cod 0' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","cod_amount_paise")
					VALUES (gen_random_uuid(), t, c, w, 0);
				WHEN 'cod -1' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","cod_amount_paise")
					VALUES (gen_random_uuid(), t, c, w, -1);
				WHEN 'cod 1000000001' THEN
					INSERT INTO "orders" ("id","tenant_id","client_id","warehouse_id","cod_amount_paise")
					VALUES (gen_random_uuid(), t, c, w, 1000000001);
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN not_null_violation THEN
				refused_by := 'not-null';
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0093: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "orders" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0093: a probe row survived.';
	END IF;
END $$;
